-- Turning tool holders (CD/CX/DN series, 54 parts) for the LEGACY tables only.
-- Already applied to staging. Run on production after backing up master_product_data,
-- master_series_data and master_price_data_jun_2026. Production has no ISO 13399 tables yet,
-- so turning_attributes is not part of this file.
-- Dimension and weight strings keep three decimals (e.g. 6.000) on purpose.

ALTER TABLE master_product_data
 ADD COLUMN lf varchar(10) NULL, ADD COLUMN lh varchar(10) NULL, ADD COLUMN hf varchar(10) NULL,
 ADD COLUMN h varchar(10) NULL, ADD COLUMN b varchar(10) NULL, ADD COLUMN wf varchar(10) NULL,
 ADD COLUMN kapr varchar(5) NULL, ADD COLUMN weight varchar(10) NULL, ADD COLUMN holder_insert varchar(25) NULL;

START TRANSACTION;
COMMIT;
